def compute(vars):
    value_2012 = vars["v1"]
    value_2011 = vars["v2"]
    maximum = max(value_2012, value_2011)

    return {
        "value": maximum,
        "trace": {
            "value_2012": value_2012,
            "value_2011": value_2011,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
